test("privileged install resume gates artifact reads and coordinator writes",()=>{
  const base="a".repeat(40),build="b".repeat(40),merge="c".repeat(40),root=mkdtempSync(join(tmpdir(),"install-resume-"));mkdirSync(join(root,"state"));
  const spec:any={authorization_id:"CESAR-BRAIN-101-OPERATOR-PROXY-20260722-01",repository:"cesarmanuel8102/AI_Vault",front_id:"BRAIN-101-INSTALL-RESUME-01",roadmap_item_id:"R1.2",expected_base_sha:base,deployment_mode:"INSTALL_ONLY",install_target:"agent_loop_worker"};
  const state:any={schema_version:1,front_id:spec.front_id,roadmap_item_id:spec.roadmap_item_id,state:"ESCALATED",issue:95,pr:58,base_sha:base,head_sha:merge,builder_session:"builder-one",reviewer_session:"reviewer-one",decision_id:"11111111-1111-4111-8111-111111111111",repair_cycles:0,deployment_mode:"INSTALL_ONLY",completed_effects:["issue:95",`build:${build}`,`merge:${merge}`],last_error:"LOCAL_PRIVILEGE_REQUIRED",updated_utc:new Date().toISOString()};
  const run=(patch:any={},options:any={})=>{let artifactReads=0,receiptReads=0,installCalls=0,resumes=0;const pause=join(root,"state","PAUSE");if(options.localPause)writeFileSync(pause,"");const bus:any={branchHead:()=>options.currentBase??base,issuePaused:()=>options.paused??false,fileAt:()=>{artifactReads++;return "worker bytes";}};const boundary=new ExternalEffectBoundary(root,bus,()=>options.lease??true),coordinator:any={validatedInstallReceiptDigest:()=>{receiptReads++;return options.receipt===false?undefined:"e".repeat(64);},install:()=>{installCalls++;return "PASS";}},flow:any={assertPrivilegedInstallState:()=>{if(options.persistedDrift)throw new Error("persisted drift");},resumePrivilegedInstall:()=>{resumes++;return {...state,state:"INSTALL_PENDING"};}};let error="";try{resumePrivilegedInstall(bus,boundary,coordinator,flow,spec,{...state,...patch});}catch(e){error=String(e);}finally{rmSync(pause,{force:true});}return {artifactReads,receiptReads,installCalls,resumes,error};};
  assert.deepEqual(run({}, {receipt:false}),{artifactReads:0,receiptReads:1,installCalls:0,resumes:0,error:""});
  for(const blocked of [run({head_sha:"invalid"}),run({}, {paused:true}),run({}, {currentBase:"d".repeat(40)}),run({}, {lease:false}),run({}, {localPause:true}),run({}, {persistedDrift:true}),run({completed_effects:["issue:95",`merge:${merge}`]})]){assert.equal(blocked.artifactReads,0);assert.equal(blocked.receiptReads,0);assert.equal(blocked.installCalls,0);assert.equal(blocked.resumes,0);assert.notEqual(blocked.error,"");}
  assert.deepEqual(run(),{artifactReads:1,receiptReads:1,installCalls:1,resumes:1,error:""});
});
