  const base="a".repeat(40),next="b".repeat(40),state:any={schema_version:1,front_id:"CLOSEOUT-PUBLISHED-RETRY",roadmap_item_id:"R3.13",state:"BUILDING",base_sha:base,issue:237,repair_cycles:1,builder_retry_reason:"BUILDER_FAILURE",deployment_mode:"NO_DEPLOY",completed_effects:["issue:237"],updated_utc:new Date().toISOString()},adopted={...state,state:"CI_PENDING",base_sha:next,pr:241,head_sha:"c".repeat(40)};
